def one_division_reverse(string):
    if len(set(string)) == 1:
        return 0

    i = 0
    num = 0
    head = 0
    while i < len(string):
        while True and i < len(string):
            if string[head] != string[i]:
                head = i
                num += 1
                i += 1
                break   
            i += 1

    return num

