def solve():
    N = int(input())
    dict = {}
    for n in range(2, N + 1):
        for i in range(2, n + 1):
            while n % i == 0:
                n //= i
                if not i in dict.keys():
                    dict[i] = 1
                else:
                    dict[i] += 1
    res = 1
    for i in dict.values():
        res *= (i + 1)
        res %= NUM
    return res

