def sum_alt_adj_cnt(arr, updown: 1) -> int:
    cnt, sum = 0, 0
    for idx in range(len(arr)):
        sum += arr[idx]
        if idx % 2 == 0:
            if sum * updown > 0:
                continue
            else:
                fix = abs(sum * updown - 1)
                sum += fix * updown
                cnt += fix
        else:
            if sum * updown * (-1) > 0:
                continue
            else:
                fix = abs(sum * updown * (-1) - 1)
                sum += fix * updown * (-1)
                cnt += fix
    return cnt


