    len_a, len_b = len(a_str), len(b_str)

    # check number of digit
    if len_a != len_b:
        return 'GREATER' if len_a > len_b else 'LESS'

    # same number of digit
    for digit_i in range(len_a):
        a_digit = int(a_str[digit_i])
        b_digit = int(b_str[digit_i])

        if a_digit == b_digit:
            continue
        else:
            return 'GREATER' if a_digit > b_digit else 'LESS'

    return 'EQUAL'

