def factorization(n):
    d = {}
    tmp = n
    for i in range(2, int(-(-sqrt(n) // 1)) + 1):
        if tmp % i == 0:
            c = 0
            while tmp % i == 0:
                tmp //= i
                c += 1
            d[i] = c
    if tmp != 1:
        d[tmp] = 1
    if len(d) == 0:
        d[n] = 1
    return d


