from collections import deque


def main():
    """
    コストの符号を反転することで最短経路問題に変換
    ちょっと特殊なベルマンフォード
    通常のベルマンフォードでは始点からたどり着ける負閉路は検出できるが
    今回の場合、負閉路から頂点Nにたどり着けない場合は無視
    参考 https://drken1215.hatenablog.com/entry/2019/02/16/075900
    """
    num_vertex, num_edge = map(int, input().split())

    adj = [[] for _ in range(num_vertex)]
    for _ in range(num_edge):
        a, b, c = map(int, input().split())
        a -= 1
        b -= 1
        adj[a].append((b, -c))

    INF = 10 ** 12
    dist = [INF for _ in range(num_vertex)]
    dist[0] = 0

    negative_cycle = [False for _ in range(num_vertex)]
    stack = deque()

    for iter in range(num_vertex):
        for now_v in range(num_vertex):
            if dist[now_v] == INF:
                continue
            for next_v, c in adj[now_v]:
                if dist[next_v] > dist[now_v] + c:
                    dist[next_v] = dist[now_v] + c
                    # 負閉路がある
                    if iter == num_vertex - 1:
                        negative_cycle[next_v] = True
                        stack.append(next_v)

    # 負閉路の影響を受ける頂点を探す
    while stack:
        now_v = stack.pop()
        for next_v, _ in adj[now_v]:
            if negative_cycle[next_v]:
                continue
            negative_cycle[next_v] = True
            stack.append(next_v)

    if negative_cycle[-1]:
        print("inf")
    else:
        print(-dist[-1])


