def resolve():
    s = input()
    ls = len(s)
    ans = 0
    for bit in range(1 << (ls - 1)):
        f = ""
        for j in range(ls - 1):
            f += s[j]
            if 1 << j & bit:
                f += "+"
        f += s[-1]
        ans += eval(f)
    print(ans)


if __name__ == "__main__":
    resolve()

