def factorization(n):
    test=n
    result=[]
    for i in range(2,int((n**0.5)+1)+1):
        if test%i==0:
            count=0
            while test%i==0:
                count+=1
                test//=i
            result.append([i,count])

    if test!=1:
        result.append([test,1])
    if result==[]:
        result.append([n,1])
    return result

