        d = {'u': d1['i'], 'v': d2['i'], 'cost': cost}
        edges.append(d)

    edges = sorted(edges, key=lambda d: d['cost'])

    ans = 0
    uf = UnionFind(N)
    for edge in edges:
        u = edge['u']
        v = edge['v']
        cost = edge['cost']

        if uf.is_same(u, v):
